public static Vector2 velocityToPositionSmooth(Body body,
                                                    Vector2 targetPosition,
                                                    float maxSpeed,
                                                    float deltaTime) {
    // Frame-rate–independent, smooth velocity toward a target that never overshoots.
    // Uses STEP_FREQUENCY for exact "arrive next step" speed and blends with deltaTime.

    final Vector2 pos = body.getPosition();
    final Vector2 vel = body.getLinearVelocity();

    float dx = targetPosition.x - pos.x;
    float dy = targetPosition.y - pos.y;
    float dist = (float)Math.hypot(dx, dy);

    // Edge cases
    if (dist <= 1e-4f || maxSpeed <= 0f || PhysicsSystem.STEP_FREQUENCY <= 0f) {
        return new Vector2(0f, 0f);
    }

    // Unit direction toward target
    float ux = dx / dist;
    float uy = dy / dist;

    // Exact speed to land on target next physics step (no overshoot)
    float arriveSpeed = dist * PhysicsSystem.STEP_FREQUENCY; // m/s
    float targetSpeed = Math.min(maxSpeed, arriveSpeed);

    // Current speed component along target direction
    float curSpeedAlong = vel.x * ux + vel.y * uy;

    // Frame-rate–independent smoothing: alpha = 1 - exp(-k * dt)
    // responsiveness k in 1/s controls how quickly velocity approaches targetSpeed
    float responsiveness = 10f; // tweak as desired
    float baseAlpha = 1f - (float)Math.exp(-Math.max(0f, responsiveness) * Math.max(0f, deltaTime));

    // Interpolated alpha (LibGDX-like smoothstep curve)
    float a = Math.max(0f, Math.min(1f, baseAlpha));
    float smoothAlpha = a * a * (3f - 2f * a); // smoothstep

    // Blend current radial speed toward target radial speed
    float newSpeed = curSpeedAlong + (targetSpeed - curSpeedAlong) * smoothAlpha;

    // Clamp to [0, arriveSpeed] to prevent overshoot even if current speed was high
    newSpeed = Math.max(0f, Math.min(newSpeed, arriveSpeed));

    // Final velocity vector
    return new Vector2(ux * newSpeed, uy * newSpeed);
}

