// TrajectoryLauncher2D.cs (C# for Unity)
// Usage / Setup:
// - Required components on the projectile GameObject: Rigidbody2D and Collider2D (2D).
// - Add this script to the projectile. It uses OnMouseDown/OnMouseDrag/OnMouseUp (works with a single touch as well).
// - Canvas:
//   - Recommended: Screen Space - Overlay (no camera assignment needed).
//   - Also supported: Screen Space - Camera / World Space (assign the Canvas to Target Canvas and ensure its World Camera is set).
// - Trajectory Dots:
//   - Create a small UI Image (e.g., a 4–8px dot) and assign it as Dot Prefab.
//   - Assign the Target Canvas where those dots should render.
// - Direction Arrow (optional):
//   - Assign a UI Image (e.g., an arrow sprite). It will rotate, position, and optionally scale with launch speed.
// - Line Renderer (optional):
//   - Add a LineRenderer to any GameObject, assign it in the inspector, and enable "Use Line Renderer".
//   - For a dashed/dotted line: enable "Dashed Line", assign a dashed/dotted material whose texture repeats, and set Dash Length (world units).
//     Make sure LineRenderer.textureMode is Tile (script sets this when dashed is enabled).

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(Collider2D))]
public class TrajectoryLauncher2D : MonoBehaviour
{
    [Header("Input & Launch")]
    [Tooltip("Multiply world drag distance by this to get launch speed.")]
    public float power = 8f;

    [Tooltip("Cap the initial speed.")]
    public float maxLaunchSpeed = 20f;

    [Tooltip("Pull back to shoot forward (slingshot style).")]
    public bool invertDrag = true;

    [Tooltip("If true, the body is kinematic while dragging so it doesn't fall.")]
    public bool freezeWhileDragging = true;

    [Header("Trajectory UI (dots)")]
    public Canvas targetCanvas;
    [Tooltip("Prefab for the dot (UI Image) to display along the trajectory.")]
    public Image dotPrefab;
    [Tooltip("How many dots to show.")]
    public int dotsCount = 20;
    [Tooltip("Time step between dots in seconds.")]
    public float dotTimeStep = 0.08f;

    [Header("Optional Direction UI")]
    [Tooltip("Optional UI Image to show direction/arrow while dragging.")]
    public Image directionImage;
    [Tooltip("Scale the arrow length with speed (set to 0 to disable scaling).")]
    public float arrowLengthScale = 5f;

    [Header("Line Renderer (optional)")]
    [Tooltip("Optionally draw the trajectory using a LineRenderer.")]
    public bool useLineRenderer = false;
    public LineRenderer lineRenderer;
    public Color lineColor = Color.white;
    public float lineWidth = 0.05f;

    [Header("Dashed/Dotted Line (optional)")]
    [Tooltip("Render the line as dashed/dotted using a tiled texture material.")]
    public bool dashedLine = false;
    [Tooltip("Material with a dashed/dotted texture set to repeat. Use a shader that supports tiling (e.g., Unlit/Transparent).")]
    public Material dashedLineMaterial;
    [Tooltip("Approximate world length (in units) per dash cycle (affects tiling).")]
    public float dashLengthWorld = 1f;
    [Tooltip("Extra tiling multiplier to tweak dash density.")]
    public float dashTilingMultiplier = 1f;
    [Tooltip("Scroll speed for the dash texture along the line (optional).")]
    public float dashScrollSpeed = 0f;

    [Header("Camera")]
    [Tooltip("Camera used to convert between screen and world. Defaults to Camera.main.")]
    public Camera cam;

    // Internal state
    private Rigidbody2D _rb;
    private List<RectTransform> _dots = new List<RectTransform>();
    private bool _dragging;
    private Vector3 _startDragScreen;
    private Vector3 _startDragWorldProjected;
    private float _zToCam; // distance from cam to object for ScreenToWorldPoint
    private Vector2 _pendingLaunchVelocity; // computed while dragging
    private RigidbodyType2D _preDragBodyType;
    private RectTransform _canvasRect;
    private Vector2 _directionBaseSize;
    private Material _originalLineMaterial;

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (cam == null) cam = Camera.main;

        if (targetCanvas == null)
        {
            // Try to find any Canvas in the scene as a fallback
            targetCanvas = FindObjectOfType<Canvas>();
        }

        if (targetCanvas != null)
        {
            _canvasRect = targetCanvas.transform as RectTransform;
        }

        if (dotPrefab != null && targetCanvas != null)
        {
            CreateDotsPool();
            HideDots();
        }

        if (directionImage != null)
        {
            _directionBaseSize = directionImage.rectTransform.sizeDelta;
            directionImage.gameObject.SetActive(false);
        }

        if (useLineRenderer && lineRenderer != null)
        {
            _originalLineMaterial = lineRenderer.sharedMaterial;
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;
            lineRenderer.startWidth = lineWidth;
            lineRenderer.endWidth = lineWidth;
            lineRenderer.startColor = lineColor;
            lineRenderer.endColor = lineColor;
            lineRenderer.useWorldSpace = true;
            ApplyLineRendererStyle();
        }
    }

    void OnValidate()
    {
        power = Mathf.Max(0f, power);
        maxLaunchSpeed = Mathf.Max(0f, maxLaunchSpeed);
        dotsCount = Mathf.Max(0, dotsCount);
        dotTimeStep = Mathf.Max(0.001f, dotTimeStep);
        lineWidth = Mathf.Max(0.001f, lineWidth);
        dashLengthWorld = Mathf.Max(0.001f, dashLengthWorld);

        if (lineRenderer != null)
        {
            lineRenderer.startWidth = lineWidth;
            lineRenderer.endWidth = lineWidth;
            lineRenderer.startColor = lineColor;
            lineRenderer.endColor = lineColor;
            ApplyLineRendererStyle();
        }
    }

    void OnDisable()
    {
        // Ensure UI and line are hidden if the object is disabled while dragging
        HideDots();
        if (directionImage != null) directionImage.gameObject.SetActive(false);
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;
        }
        _dragging = false;
    }

    void CreateDotsPool()
    {
        // Clear existing
        foreach (var d in _dots)
        {
            if (d != null) Destroy(d.gameObject);
        }
        _dots.Clear();

        if (dotPrefab == null || targetCanvas == null) return;

        for (int i = 0; i < dotsCount; i++)
        {
            var dot = Instantiate(dotPrefab, targetCanvas.transform);
            dot.transform.SetAsLastSibling();
            dot.gameObject.name = $"TrajectoryDot_{i}";
            dot.gameObject.SetActive(false);
            _dots.Add(dot.rectTransform);
        }
    }

    void EnsureDotsPool()
    {
        if (dotPrefab == null || targetCanvas == null) return;
        if (_dots.Count != dotsCount)
        {
            CreateDotsPool();
        }
    }

    void ShowDots()
    {
        foreach (var d in _dots)
        {
            if (d != null && !d.gameObject.activeSelf)
                d.gameObject.SetActive(true);
        }
    }

    void HideDots()
    {
        foreach (var d in _dots)
        {
            if (d != null && d.gameObject.activeSelf)
                d.gameObject.SetActive(false);
        }
    }

    void OnMouseDown()
    {
        if (cam == null) cam = Camera.main;

        _dragging = true;
        _startDragScreen = Input.mousePosition;

        // Compute depth relative to camera for consistent ScreenToWorldPoint conversion
        if (cam != null)
        {
            _zToCam = cam.WorldToScreenPoint(transform.position).z;
        }
        else
        {
            _zToCam = 0f;
        }

        _startDragWorldProjected = ScreenToWorldWithZ(_startDragScreen);

        if (freezeWhileDragging)
        {
            _preDragBodyType = _rb.bodyType;
            _rb.velocity = Vector2.zero;
            _rb.angularVelocity = 0f;
            _rb.bodyType = RigidbodyType2D.Kinematic;
        }

        EnsureDotsPool();
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = true;
            lineRenderer.positionCount = 0;
        }
        if (directionImage != null)
        {
            directionImage.gameObject.SetActive(true);
        }

        // Initialize preview with zero velocity (no movement) until dragging motion
        _pendingLaunchVelocity = Vector2.zero;
        UpdateTrajectoryPreview(_pendingLaunchVelocity);
    }

    void OnMouseDrag()
    {
        if (!_dragging) return;

        Vector3 currentWorld = ScreenToWorldWithZ(Input.mousePosition);
        Vector2 dragVector = (Vector2)(currentWorld - _startDragWorldProjected);

        Vector2 launchVel = dragVector * power;
        if (invertDrag) launchVel = -launchVel;
        launchVel = Vector2.ClampMagnitude(launchVel, maxLaunchSpeed);
        _pendingLaunchVelocity = launchVel;

        UpdateTrajectoryPreview(_pendingLaunchVelocity);
    }

    void OnMouseUp()
    {
        if (!_dragging) return;

        _dragging = false;

        // Hide helpers
        HideDots();
        if (directionImage != null) directionImage.gameObject.SetActive(false);
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;
        }

        // Restore body type and apply pending velocity
        if (freezeWhileDragging)
        {
            _rb.bodyType = _preDragBodyType;
        }

        // Apply launch velocity; ensure dynamic to be affected by physics
        if (_rb.bodyType == RigidbodyType2D.Kinematic)
        {
            _rb.bodyType = RigidbodyType2D.Dynamic;
        }
        _rb.velocity = _pendingLaunchVelocity;
    }

    void UpdateTrajectoryPreview(Vector2 launchVelocity)
    {
        // Show dots if available
        if (_dots.Count > 0) ShowDots();

        // Update direction arrow (optional)
        UpdateDirectionImage(launchVelocity);

        // Calculate predicted world positions
        Vector2 p0 = transform.position;
        Vector2 v0 = launchVelocity;
        Vector2 a = Physics2D.gravity * _rb.gravityScale;

        // Prepare line renderer positions if in use
        Vector3[] linePositions = null;
        int lineCount = Mathf.Max(0, dotsCount);
        if (useLineRenderer && lineRenderer != null)
        {
            linePositions = new Vector3[lineCount];
        }

        // Canvas camera for screen-to-canvas conversion
        Camera canvasCam = GetCanvasCamera();

        for (int i = 0; i < dotsCount; i++)
        {
            float t = (i + 1) * dotTimeStep; // start after a small delta so the first dot isn't at p0
            Vector2 worldPos2D = p0 + v0 * t + 0.5f * a * t * t;
            Vector3 worldPos3D = new Vector3(worldPos2D.x, worldPos2D.y, transform.position.z);

            // Update UI dots (Canvas)
            if (targetCanvas != null && _dots != null && i < _dots.Count && _dots[i] != null)
            {
                Vector2 anchoredPos;
                Vector2 screenPos = cam != null ? (Vector2)cam.WorldToScreenPoint(worldPos3D) : Vector2.zero;
                if (_canvasRect != null && RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screenPos, canvasCam, out anchoredPos))
                {
                    _dots[i].anchoredPosition = anchoredPos;
                    if (!_dots[i].gameObject.activeSelf) _dots[i].gameObject.SetActive(true);
                }
                else
                {
                    if (_dots[i].gameObject.activeSelf) _dots[i].gameObject.SetActive(false);
                }
            }

            // Collect for line renderer
            if (linePositions != null && i < linePositions.Length)
            {
                linePositions[i] = worldPos3D;
            }
        }

        // Apply line positions if used
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = true;
            lineRenderer.positionCount = linePositions != null ? linePositions.Length : 0;
            if (linePositions != null && linePositions.Length > 0)
            {
                lineRenderer.SetPositions(linePositions);
                UpdateDashedAppearance(linePositions);
            }
        }
    }

    void UpdateDirectionImage(Vector2 launchVelocity)
    {
        if (directionImage == null) return;

        float speed = launchVelocity.magnitude;

        // Show/hide depending on drag state and speed
        if (_dragging && speed > 1e-3f)
        {
            if (!directionImage.gameObject.activeSelf)
                directionImage.gameObject.SetActive(true);
        }
        else
        {
            if (directionImage.gameObject.activeSelf)
                directionImage.gameObject.SetActive(false);
            return;
        }

        // Determine which canvas the direction image belongs to
        Canvas dirCanvas = directionImage.canvas != null ? directionImage.canvas : targetCanvas;
        RectTransform dirCanvasRect = dirCanvas != null ? (RectTransform)dirCanvas.transform : null;

        // Pick the correct camera for canvas space
        Camera canvasCam = GetCanvasCameraFor(dirCanvas);

        // Position the arrow at the object's position in the UI canvas
        if (cam != null && dirCanvasRect != null)
        {
            Vector3 worldPos = transform.position;
            Vector2 screenPos = cam.WorldToScreenPoint(worldPos);

            Vector2 anchoredPos;
            if (RectTransformUtility.ScreenPointToLocalPointInRectangle(dirCanvasRect, screenPos, canvasCam, out anchoredPos))
            {
                directionImage.rectTransform.anchoredPosition = anchoredPos;
            }
        }

        // Rotate the arrow to match the launch velocity direction
        float angle = Mathf.Atan2(launchVelocity.y, launchVelocity.x) * Mathf.Rad2Deg;
        Vector3 euler = directionImage.rectTransform.localEulerAngles;
        euler.z = angle;
        directionImage.rectTransform.localEulerAngles = euler;

        // Length-scale by speed if enabled
        if (arrowLengthScale > 0f)
        {
            float extraLength = speed * arrowLengthScale;
            directionImage.rectTransform.sizeDelta = new Vector2(_directionBaseSize.x + extraLength, _directionBaseSize.y);
        }
        else
        {
            directionImage.rectTransform.sizeDelta = _directionBaseSize;
        }
    }

    // LineRenderer dashed style handling
    void ApplyLineRendererStyle()
    {
        if (lineRenderer == null) return;

        if (dashedLine && dashedLineMaterial != null)
        {
            lineRenderer.textureMode = LineTextureMode.Tile;
            lineRenderer.sharedMaterial = dashedLineMaterial;
        }
        else
        {
            lineRenderer.textureMode = LineTextureMode.Stretch;
            lineRenderer.sharedMaterial = _originalLineMaterial;
        }
    }

    void UpdateDashedAppearance(Vector3[] positions)
    {
        if (lineRenderer == null) return;

        // Ensure current style is applied (in case toggled at runtime)
        ApplyLineRendererStyle();

        if (!(dashedLine && dashedLineMaterial != null)) return;

        // Compute total path length to derive tiling amount
        float length = 0f;
        for (int i = 1; i < positions.Length; i++)
        {
            length += Vector3.Distance(positions[i - 1], positions[i]);
        }

        float cycles = Mathf.Max(0.001f, length / Mathf.Max(0.001f, dashLengthWorld)) * Mathf.Max(0.001f, dashTilingMultiplier);

        // Instance the material so we don't modify shared asset at runtime
        if (lineRenderer.material == null || lineRenderer.material == lineRenderer.sharedMaterial)
        {
            lineRenderer.material = new Material(lineRenderer.sharedMaterial);
        }

        // Set tiling (x = along line, y = keep as 1)
        Vector2 tiling = new Vector2(cycles, 1f);
        lineRenderer.material.mainTextureScale = tiling;

        if (dashScrollSpeed != 0f)
        {
            Vector2 offset = lineRenderer.material.mainTextureOffset;
            offset.x += dashScrollSpeed * Time.deltaTime;
            lineRenderer.material.mainTextureOffset = offset;
        }
    }

    // Helper: get canvas camera for a given canvas (null for Screen Space - Overlay)
    Camera GetCanvasCameraFor(Canvas canvas)
    {
        if (canvas == null) return null;
        return canvas.renderMode == RenderMode.ScreenSpaceOverlay ? null : canvas.worldCamera;
    }

    // Helper: get canvas camera for targetCanvas (null for Screen Space - Overlay)
    Camera GetCanvasCamera()
    {
        if (targetCanvas == null) return null;
        return targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay ? null : targetCanvas.worldCamera;
    }

    // Helper: Screen to world using stored Z distance from camera
    Vector3 ScreenToWorldWithZ(Vector3 screenPos)
    {
        if (cam == null) return transform.position;
        screenPos.z = _zToCam;
        return cam.ScreenToWorldPoint(screenPos);
    }
}
